#### Phase 2: Implement Link Building (Week 3-4)

**Step 4: Create Link Builder Base Class**

```csharp
// LinkBuilderBase.cs
using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;

public abstract class LinkBuilderBase<TResource>
{
    protected readonly IUrlHelper UrlHelper;
    protected readonly IAuthorizationService AuthService;

    protected LinkBuilderBase(
        IUrlHelper urlHelper,
        IAuthorizationService authService)
    {
        UrlHelper = urlHelper;
        AuthService = authService;
    }

    public abstract Task<Dictionary<string, Link>> BuildLinksAsync(
        TResource resource,
        ClaimsPrincipal user);

    protected Link CreateLink(string routeName, object routeValues = null,
        string title = null, string method = "GET")
    {
        return new Link
        {
            Href = UrlHelper.Link(routeName, routeValues),
            Title = title,
            Method = method
        };
    }

    protected async Task<bool> UserCanPerformActionAsync(
        ClaimsPrincipal user,
        TResource resource,
        string policyName)
    {
        var authResult = await AuthService.AuthorizeAsync(
            user, resource, policyName);
        return authResult.Succeeded;
    }
}

public class Link
{
    public string Href { get; set; }
    public string Title { get; set; }
    public string Method { get; set; } = "GET";
    public string Type { get; set; }
    public bool Templated { get; set; }
}
```

**Step 5: Implement Resource-Specific Link Builders**

```csharp
// ClaimLinkBuilder.cs
public class ClaimLinkBuilder : LinkBuilderBase<Claim>
{
    private readonly IClaimStateService _stateService;

    public ClaimLinkBuilder(
        IUrlHelper urlHelper,
        IAuthorizationService authService,
        IClaimStateService stateService)
        : base(urlHelper, authService)
    {
        _stateService = stateService;
    }

    public override async Task<Dictionary<string, Link>> BuildLinksAsync(
        Claim claim,
        ClaimsPrincipal user)
    {
        var links = new Dictionary<string, Link>();

        // Self link (always included)
        links["self"] = CreateLink(
            "GetClaim",
            new { id = claim.ClaimId },
            $"Claim {claim.ClaimId}"
        );

        // Collection link
        links["collection"] = CreateLink(
            "GetClaims",
            null,
            "All Claims"
        );

        // Related resources
        links["member"] = CreateLink(
            "GetMember",
            new { id = claim.MemberId },
            "Member Details"
        );

        links["provider"] = CreateLink(
            "GetProvider",
            new { id = claim.ProviderId },
            "Provider Details"
        );

        // State-based action links
        await AddStateBasedLinksAsync(claim, user, links);

        // Conditional business rule links
        await AddConditionalLinksAsync(claim, user, links);

        // Documentation link
        links["documentation"] = new Link
        {
            Href = $"https://developer.gainwell.com/claims/{claim.Status.ToLower()}",
            Title = $"Documentation for {claim.Status} claims",
            Type = "text/html"
        };

        return links;
    }

    private async Task AddStateBasedLinksAsync(
        Claim claim,
        ClaimsPrincipal user,
        Dictionary<string, Link> links)
    {
        var availableActions = _stateService.GetAvailableActions(claim.Status);

        foreach (var action in availableActions)
        {
            // Check user authorization
            if (await UserCanPerformActionAsync(user, claim, action.Policy))
            {
                links[action.RelationType] = CreateLink(
                    action.RouteName,
                    new { id = claim.ClaimId },
                    action.Description,
                    action.HttpMethod
                );
            }
        }
    }

    private async Task AddConditionalLinksAsync(
        Claim claim,
        ClaimsPrincipal user,
        Dictionary<string, Link> links)
    {
        // Cancel link available for 24 hours after submission
        if (claim.Status == ClaimStatus.Submitted &&
            DateTime.UtcNow < claim.SubmittedDate.AddHours(24) &&
            await UserCanPerformActionAsync(user, claim, "Claims.Cancel"))
        {
            links["cancel"] = CreateLink(
                "CancelClaim",
                new { id = claim.ClaimId },
                "Cancel Claim (available for 24 hours)",
                "POST"
            );
        }

        // Attachment link if documents required
        if (claim.RequiresAttachments &&
            await UserCanPerformActionAsync(user, claim, "Claims.AddAttachment"))
        {
            links["add-attachment"] = CreateLink(
                "AddClaimAttachment",
                new { id = claim.ClaimId },
                "Upload Supporting Documentation",
                "POST"
            );
            links["add-attachment"].Type = "multipart/form-data";
        }

        // Remittance advice for paid claims
        if (claim.Status == ClaimStatus.Paid)
        {
            links["remittance-advice"] = CreateLink(
                "GetRemittanceAdvice",
                new { id = claim.ClaimId },
                "Download Remittance Advice"
            );
            links["remittance-advice"].Type = "application/pdf";
        }
    }
}
```

**Step 6: Create HAL Response Wrapper**

```csharp
// HalResource.cs
public class HalResource<T>
{
    [JsonProperty("_links")]
    public Dictionary<string, Link> Links { get; set; } = new();

    [JsonProperty("_embedded")]
    public Dictionary<string, object> Embedded { get; set; } = new();

    // Flatten resource properties to root
    [JsonExtensionData]
    public Dictionary<string, object> Properties { get; set; } = new();

    public HalResource(T resource, Dictionary<string, Link> links)
    {
        Links = links;

        // Copy resource properties
        var properties = typeof(T).GetProperties();
        foreach (var prop in properties)
        {
            Properties[ToCamelCase(prop.Name)] = prop.GetValue(resource);
        }
    }

    public HalResource<T> Embed(string rel, object embeddedResource)
    {
        Embedded[rel] = embeddedResource;
        return this;
    }

    private string ToCamelCase(string str)
    {
        if (string.IsNullOrEmpty(str) || char.IsLower(str[0]))
            return str;
        return char.ToLower(str[0]) + str.Substring(1);
    }
}
```

