#### Phase 3: API Controller Integration (Week 5-6)

**Step 7: Update API Controllers to Return HAL Responses**

```csharp
// ClaimsController.cs
[ApiController]
[Route("api/v1/claims")]
public class ClaimsController : ControllerBase
{
    private readonly IClaimService _claimService;
    private readonly ClaimLinkBuilder _linkBuilder;

    public ClaimsController(
        IClaimService claimService,
        ClaimLinkBuilder linkBuilder)
    {
        _claimService = claimService;
        _linkBuilder = linkBuilder;
    }

    [HttpGet("{id}", Name = "GetClaim")]
    [Produces("application/hal+json")]
    [ProducesResponseType(typeof(HalResource<Claim>), 200)]
    public async Task<IActionResult> GetClaim(string id)
    {
        var claim = await _claimService.GetClaimAsync(id);

        if (claim == null)
            return NotFound();

        // Build hypermedia links
        var links = await _linkBuilder.BuildLinksAsync(claim, User);

        // Create HAL response
        var halResource = new HalResource<Claim>(claim, links);

        // Optionally embed related resources
        if (ShouldEmbedMember())
        {
            var member = await _memberService.GetMemberAsync(claim.MemberId);
            var memberLinks = await _memberLinkBuilder.BuildLinksAsync(member, User);
            halResource.Embed("member", new HalResource<Member>(member, memberLinks));
        }

        return Ok(halResource);
    }

    [HttpPost(Name = "CreateClaim")]
    [Produces("application/hal+json")]
    public async Task<IActionResult> CreateClaim([FromBody] CreateClaimRequest request)
    {
        var claim = await _claimService.CreateClaimAsync(request);

        var links = await _linkBuilder.BuildLinksAsync(claim, User);
        var halResource = new HalResource<Claim>(claim, links);

        return CreatedAtRoute("GetClaim", new { id = claim.ClaimId }, halResource);
    }

    [HttpPost("{id}/submit", Name = "SubmitClaim")]
    [Produces("application/hal+json")]
    public async Task<IActionResult> SubmitClaim(string id)
    {
        var claim = await _claimService.SubmitClaimAsync(id);

        if (claim == null)
            return NotFound();

        // Links will reflect new "Submitted" status
        var links = await _linkBuilder.BuildLinksAsync(claim, User);
        var halResource = new HalResource<Claim>(claim, links);

        return Ok(halResource);
    }
}
```

**Step 8: Configure Content Negotiation**

```csharp
// Program.cs
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllers()
    .AddJsonOptions(options =>
    {
        // Configure HAL+JSON formatting
        options.JsonSerializerOptions.PropertyNamingPolicy =
            JsonNamingPolicy.CamelCase;
        options.JsonSerializerOptions.DefaultIgnoreCondition =
            JsonIgnoreCondition.WhenWritingNull;
    });

// Register custom media type formatter for HAL
builder.Services.Configure<MvcOptions>(options =>
{
    options.OutputFormatters.Add(new HalJsonOutputFormatter());
    options.FormatterMappings.SetMediaTypeMappingForFormat(
        "hal+json", "application/hal+json");
});

// Register link builders
builder.Services.AddScoped<ClaimLinkBuilder>();
builder.Services.AddScoped<MemberLinkBuilder>();
builder.Services.AddScoped<ProviderLinkBuilder>();
```

