[patterns/application/api-microservices/PTN-APP-API-013-hateoas-pattern.md#configuration-examples]

### Configuration Examples

**JavaScript Client Example**:

```javascript
// HAL client for provider portal
class HalClient {
  constructor(baseUrl, authToken) {
    this.baseUrl = baseUrl;
    this.authToken = authToken;
  }

  async get(url) {
    const response = await fetch(url || this.baseUrl, {
      headers: {
        'Accept': 'application/hal+json',
        'Authorization': `Bearer ${this.authToken}`
      }
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return await response.json();
  }

  async followLink(resource, rel) {
    if (!resource._links || !resource._links[rel]) {
      throw new Error(`Link relation '${rel}' not found`);
    }

    const link = resource._links[rel];
    return await this.get(link.href);
  }

  async performAction(resource, rel, data = null) {
    if (!resource._links || !resource._links[rel]) {
      throw new Error(`Action '${rel}' not available`);
    }

    const link = resource._links[rel];
    const method = link.method || 'GET';

    const options = {
      method,
      headers: {
        'Accept': 'application/hal+json',
        'Authorization': `Bearer ${this.authToken}`
      }
    };

    if (data) {
      options.headers['Content-Type'] = 'application/json';
      options.body = JSON.stringify(data);
    }

    const response = await fetch(link.href, options);

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return await response.json();
  }

  hasLink(resource, rel) {
    return resource._links && resource._links[rel] !== undefined;
  }

  getLinkTitle(resource, rel) {
    return resource._links?.[rel]?.title || rel;
  }
}

// Usage in provider portal
const client = new HalClient('https://api.gainwell.com', authToken);

// Get claim with hypermedia
const claim = await client.get('/api/v1/claims/CLM-123');

// Render UI based on available links
if (client.hasLink(claim, 'cancel')) {
  renderCancelButton(claim, async () => {
    const updatedClaim = await client.performAction(claim, 'cancel');
    refreshUI(updatedClaim);
  });
}

if (client.hasLink(claim, 'add-attachment')) {
  renderUploadButton(claim, async (file) => {
    const formData = new FormData();
    formData.append('file', file);

    const link = claim._links['add-attachment'];
    const response = await fetch(link.href, {
      method: 'POST',
      body: formData,
      headers: {'Authorization': `Bearer ${authToken}`}
    });

    const updatedClaim = await response.json();
    refreshUI(updatedClaim);
  });
}

// Navigate to related resources
const member = await client.followLink(claim, 'member');
const provider = await client.followLink(claim, 'provider');
```

